export const BODY: string = "\n<p>تصویر فون پر سیدھی لگتی ہے، مگر ویب سائٹ پر الٹی یا ترچھی کھلتی ہے۔ یہ تصویر خراب نہیں ہوئی، بلکہ اس کی سمت کی معلومات غلط پڑھی گئی ہے۔</p>\n<p>اس کی وجہ EXIF اورینٹیشن ہے: فون تصویر کے پکسلز گھمائے بغیر صرف ایک عدد لکھ دیتا ہے، جو بتاتا ہے کہ تصویر کس سمت میں دکھانی ہے۔ جو پروگرام اس عدد کو نہیں پڑھتا، وہ تصویر کو غلط سمت میں دکھاتا ہے۔</p>\n<p>یہ مضمون آٹھ سمتوں کی وضاحت، ٹوٹنے کی جگہیں، مستقل ٹھیک کرنے کا طریقہ اور پرائیویسی کا تعلق بتاتا ہے۔ گھمانے کے لیے <a href=\"/ur/tasveer-ghumayein-ultayein/\">روٹیٹ فلپ امیج</a> استعمال کریں۔</p>\n<h2 id=\"what-is-exif-orientation\">EXIF اورینٹیشن کیا ہے؟</h2>\n<p>EXIF اورینٹیشن فائل میں لکھا ایک عدد ہے، جو 1 سے 8 تک ہوتا ہے اور بتاتا ہے کہ تصویر کو کتنا گھمانا یا پلٹنا ہے۔ فون تصویر لیتے وقت پکسلز گھماتا نہیں، صرف یہ عدد لکھ دیتا ہے۔</p>\n<p>یہ طریقہ تیز ہے، کیونکہ پکسلز گھمانے میں وقت اور بیٹری لگتی ہے۔ لیکن ہر پروگرام اس عدد کو نہیں پڑھتا، اور وہیں مسئلہ شروع ہوتا ہے۔</p>\n<h2 id=\"the-eight-orientation-values\">آٹھ سمتوں کی سادہ وضاحت</h2>\n<p>آٹھ عدد آٹھ حالتوں کو ظاہر کرتے ہیں: سیدھی، 90 درجے دائیں، 90 درجے بائیں، الٹی، اور ان کی آئینہ دار شکلیں۔ عدد 1 کا مطلب ہے تصویر پہلے ہی سیدھی ہے، اسے کچھ کرنے کی ضرورت نہیں۔</p>\n<p>عدد 6 سب سے عام ہے: اس کا مطلب ہے تصویر کو 90 درجے گھمانا ہے، جو فون کو سیدھا پکڑ کر لی گئی تصویر میں ہوتا ہے۔ باقی عدد سیلفی اور آئینہ دار تصویروں میں آتے ہیں۔</p>\n<h2 id=\"why-phones-store-orientation-this-way\">فون پکسلز گھمائے بغیر سمت کیوں محفوظ کرتے ہیں</h2>\n<p>فون کیمرے کا سینسر ہمیشہ ایک ہی سمت میں تصویر لیتا ہے، چاہے فون کسی بھی سمت میں پکڑا ہو۔ پکسلز گھمانے کے بجائے فون صرف سمت کا عدد لکھ دیتا ہے، جو تیز اور بیٹری بچانے والا طریقہ ہے۔</p>\n<p>یہ ڈیزائن اس وقت کام کرتا ہے جب ہر پروگرام عدد کو پڑھے۔ بدقسمتی سے پرانے پروگرام، کچھ ویب سائٹس اور پرنٹر اس عدد کو نظر انداز کر دیتے ہیں۔</p>\n<h2 id=\"where-orientation-breaks\">سمت کہاں ٹوٹتی ہے</h2>\n<p>سمت اکثر ای میل، پرانی ویب سائٹ، پرنٹ لیب اور چیٹ ایپ میں ٹوٹتی ہے۔ تصویر بھیجنے والے کو سیدھی لگتی ہے، مگر وصول کرنے والے کو ترچھی نظر آتی ہے۔</p>\n<p>فارمیٹ بدلنے پر بھی سمت ٹوٹ سکتی ہے، خاص طور پر جب کنورٹر میٹا ڈیٹا ہٹا دے۔ اسی لیے تبدیلی کے بعد تصویر کو دوبارہ جانچنا ضروری ہے۔</p>\n<h2 id=\"detecting-an-orientation-problem\">سمت کا مسئلہ کیسے پہچانیں</h2>\n<p>اگر تصویر ایک جگہ سیدھی اور دوسری جگہ ترچھی لگے تو مسئلہ سمت کا ہے، تصویر کا نہیں۔ میٹا ڈیٹا ویور میں اورینٹیشن کا عدد دیکھ کر تصدیق کریں۔</p>\n<p>اگر عدد 1 سے زیادہ ہو اور تصویر ترچھی دکھائی دے تو پروگرام عدد کو نظر انداز کر رہا ہے۔ اس کا حل پکسلز کو واقعی گھمانا ہے، نہ کہ عدد پر بھروسہ کرنا۔</p>\n<h2 id=\"fixing-orientation-permanently\">سمت کو مستقل طور پر ٹھیک کرنا</h2>\n<p>مستقل حل یہ ہے کہ تصویر کو سیدھا گھمائیں اور نئی فائل محفوظ کریں، جس میں پکسلز خود سیدھے ہوں اور عدد 1 ہو۔ اس کے بعد ہر پروگرام تصویر کو سیدھا دکھائے گا۔</p>\n<p>روٹیٹ ٹول یہی کرتا ہے: وہ پکسلز گھماتا ہے اور سمت کا عدد صاف کرتا ہے۔ ایک بار ٹھیک کی گئی تصویر ہر جگہ سیدھی رہتی ہے۔</p>\n<h2 id=\"orientation-vs-rotation\">سمت کا میٹا ڈیٹا بمقابلہ اصل گھماؤ</h2>\n<p>سمت کا میٹا ڈیٹا صرف ہدایت ہے، جبکہ اصل گھماؤ پکسلز کی تبدیلی ہے۔ ہدایت پر بھروسہ کرنا خطرناک ہے، کیونکہ ہر پروگرام اسے نہیں مانتا۔</p>\n<p>اصل گھماؤ ہر جگہ کام کرتا ہے، کیونکہ پکسلز خود سیدھے ہوتے ہیں۔ اہم تصویروں کے لیے ہمیشہ اصل گھماؤ چنیں، ہدایت پر بھروسہ نہ کریں۔</p>\n<h2 id=\"selfies-and-mirroring\">سیلفی، آئینہ اور سمت کے عدد</h2>\n<p>سیلفی میں فون اکثر تصویر کو آئینہ دار بنا دیتا ہے، تاکہ پیش منظر میں آپ خود کو ویسا دیکھیں جیسا آئینے میں دیکھتے ہیں۔ اس آئینہ دار حالت کو بھی سمت کے عدد سے ظاہر کیا جاتا ہے۔</p>\n<p>اگر سیلفی کا متن الٹا نظر آئے تو مسئلہ آئینہ دار سمت ہے۔ تصویر کو افقی سمت میں پلٹ کر درست کریں، اور پھر محفوظ کریں۔</p>\n<h2 id=\"exif-and-privacy\">EXIF سمت اور پرائیویسی</h2>\n<p>سمت کا عدد خود کوئی نجی معلومات نہیں رکھتا، مگر اس کے ساتھ موجود EXIF میں مقام اور وقت بھی ہو سکتا ہے۔ سمت ٹھیک کرتے وقت میٹا ڈیٹا بھی جانچ لیں۔</p>\n<p>تصویر شیئر کرنے سے پہلے میٹا ڈیٹا صاف کرنا محفوظ عادت ہے۔ سمت ٹھیک ہو جائے اور مقام ہٹ جائے، تو تصویر ہر لحاظ سے شیئر کرنے کے لیے تیار ہے۔</p>\n<h2 id=\"orientation-in-different-formats\">JPG، PNG اور WebP میں سمت</h2>\n<p>JPG میں سمت کا عدد EXIF میں لکھا ہوتا ہے اور زیادہ تر پروگرام اسے پڑھتے ہیں۔ PNG میں بھی سمت لکھی جا سکتی ہے، مگر کم پروگرام اسے مانتے ہیں۔</p>\n<p>WebP میں سمت کی حمایت نئی ہے اور ہر جگہ یکساں نہیں۔ فارمیٹ بدلتے وقت سمت کو پکسلز میں ٹھیک کر لینا سب سے محفوظ طریقہ ہے۔</p>\n<h2 id=\"orientation-after-conversion\">فارمیٹ بدلنے کے بعد سمت کے مسائل</h2>\n<p>فارمیٹ بدلنے والا ٹول اگر میٹا ڈیٹا ہٹا دے تو سمت کا عدد بھی ختم ہو جاتا ہے، اور تصویر ترچھی رہ جاتی ہے۔ اسی لیے تبدیلی کے بعد تصویر کو ہمیشہ دوبارہ دیکھیں۔</p>\n<p>محفوظ طریقہ یہ ہے: پہلے سمت ٹھیک کریں، پھر فارمیٹ بدلیں۔ اس ترتیب سے نئی فائل میں پکسلز پہلے ہی سیدھے ہوتے ہیں۔</p>\n<h2 id=\"orientation-and-social-media\">سوشل میڈیا اور پیغام رسانی ایپس پر سمت</h2>\n<p>زیادہ تر بڑی سوشل ایپس سمت کا عدد پڑھتی ہیں، اس لیے تصویر وہاں سیدھی نظر آتی ہے۔ لیکن چھوٹی ایپس اور پرانے فون اکثر عدد کو نظر انداز کرتے ہیں۔</p>\n<p>اہم تصویر پوسٹ کرنے سے پہلے اسے کسی اور فون پر دیکھ لیں۔ اگر وہاں بھی سیدھی لگے تو پوسٹ محفوظ ہے۔</p>\n<h2 id=\"common-myths\">تصویر کی سمت کے بارے میں عام غلط فہمیاں</h2>\n<p>ایک غلط فہمی یہ ہے کہ ترچھی تصویر خراب یا کرپٹ ہے۔ حقیقت یہ ہے کہ پکسلز بالکل ٹھیک ہیں، صرف سمت کی ہدایت غلط پڑھی گئی ہے۔</p>\n<p>دوسری غلط فہمی یہ ہے کہ فون پر سیدھی لگنے والی تصویر ہر جگہ سیدھی ہوگی۔ فون عدد پڑھتا ہے، مگر ہر پروگرام نہیں پڑھتا، اس لیے فرق آتا ہے۔</p>\n<h2 id=\"orientation-in-print-services\">پرنٹ سروس اور کیوسک میں سمت</h2>\n<p>پرنٹ لیب اور کیوسک اکثر سمت کا عدد نظر انداز کرتے ہیں، اس لیے ترچھی تصویر ترچھی ہی پرنٹ ہو جاتی ہے۔ پرنٹ کروانے سے پہلے سمت کو پکسلز میں ٹھیک کرنا ضروری ہے۔</p>\n<p>پرنٹ سے پہلے تصویر کو کمپیوٹر پر کھول کر دیکھیں۔ اگر وہاں سیدھی لگے تو پرنٹ بھی سیدھا نکلے گا۔</p>\n<h2 id=\"orientation-and-backup-services\">سمت اور کلاؤڈ بیک اپ</h2>\n<p>کلاؤڈ بیک اپ عام طور پر اصل فائل اور اس کا میٹا ڈیٹا محفوظ رکھتا ہے، اس لیے سمت بھی محفوظ رہتی ہے۔ لیکن بیک اپ سے ڈاؤن لوڈ کی گئی تصویر کو دوبارہ جانچنا اچھا ہے۔</p>\n<p>کچھ بیک اپ سروس تصویر کو کمپریس کر کے محفوظ کرتی ہیں، جس سے میٹا ڈیٹا ختم ہو سکتا ہے۔ اہم تصویروں کی اصل نقل الگ رکھیں۔</p>\n<h2 id=\"orientation-in-old-software\">پرانے سافٹ ویئر اور ایمبیڈڈ نظام میں سمت</h2>\n<p>پرانا سافٹ ویئر، جیسے دس سال پرانا فوٹو ویور یا فیکس مشین، سمت کا عدد بالکل نہیں جانتا۔ ان پر تصویر ہمیشہ سینسر کی اصل سمت میں دکھائی دیتی ہے۔</p>\n<p>ایسے نظاموں کے لیے تصویر بھیجنے سے پہلے پکسلز گھما کر محفوظ کریں۔ یہی واحد طریقہ ہے جو ہر پرانے نظام پر کام کرتا ہے۔</p>\n<h2 id=\"orientation-testing-checklist\">تصویر شیئر کرنے سے پہلے فوری جانچ فہرست</h2>\n<p>تصویر کو دو جگہوں پر دیکھیں: اپنے فون اور کمپیوٹر پر۔ دونوں پر سیدھی لگے تو سمت ٹھیک ہے۔ میٹا ڈیٹا ویور میں عدد 1 ہونا چاہیے۔</p>\n<p>اگر کہیں ترچھی لگے تو گھمائیں، محفوظ کریں اور دوبارہ جانچیں۔ گھمانے کے عملی مراحل <a href=\"/ur/blog/tasveer-kaise-ghumayein-ultayein/\">تصویر کیسے گھمائیں اور پلٹیں</a> اور مکمل رہنما <a href=\"/ur/blog/tasveer-ghumana-ultana-rehnumai/\">روٹیٹ فلپ رہنما</a> میں دیکھیں۔ میٹا ڈیٹا جانچنے کے لیے <a href=\"/ur/tasveer-metadata-dekhein/\">میٹا ڈیٹا ویور</a> اور صاف کرنے کے لیے <a href=\"/ur/tasveer-metadata-hatayein/\">میٹا ڈیٹا ہٹائیں</a>۔ پرائیویسی کی تفصیل <a href=\"/ur/blog/photo-privacy-gps-exif-khatrat/\">تصویر کی پرائیویسی اور GPS خطرہ</a> میں پڑھیں۔</p>\n";

